#!/bin/bash
# usage: check_moves.sh    every stance with every move (hers and the Jester's kept ones): reports any broken number in a bone or a vertex bound, and where the head ends up
cd /home/claude/fox3d && python3 shoot2.py shots/chk 'new Promise(r => setTimeout(() => { const st = ["", "kneel", "squat", "sit_chair", "sit_ground", "hover"], mv = ["jump", "talk", "wave", "laugh", "dance", "curtsey", "pounce", "bow", "twirl", "jester_talk", "jester_laugh", "jester_dance", "look_around", "settle", "shears_out", "hemline_fangs", "blue_mischief", "borrowed_face", "same_cloth", "slip_stitch", "crazy_quilt"], bad = []; let n = 0; const j = T.j; for (const s of st) { T.st(s, 1.2); for (const m of mv) { n++; T.at(m, 0.8); let ok = true; j.root.traverse((o) => { if (o.isBone) { const e = o.matrixWorld.elements; for (let i = 0; i < 16; i++) if (!isFinite(e[i])) ok = false; } }); if (!ok) bad.push(s + "+" + m); } } T.st("", 1.5); T.step(60, 1/60); const hp = new THREE.Vector3(); j.debug.SK.head.getWorldPosition(hp); r(JSON.stringify({ pairs: n, bad, headY: +hp.y.toFixed(4), headLocalY: +j.debug.SK.head.position.y.toFixed(4), headScale: j.debug.SK.head.scale.x })); }, 1500))' 2>&1 | tail -2
